INSERT INTO product (descripcion, name, price, stock, category_id,imagefile) VALUES('Para quienes siempre se esfuerzan por mejorar, la XRC 1200 SPLINE es tu billete a la cima. Experimenta una aceleración mejorada y una agilidad perfeccionada para ponerte a la cabeza. Una técnica de vanguardia para la máxima compresión de la capa de carbono se traduce en nuestras llantas de MTB más ligeras hasta la fecha. Ambas ruedas llevan 24 radios DT revolite. Con una llanta más ligera en la rueda delantera para aumentar la agilidad y nuestro buje para MTB más ligero en la rueda trasera, es nuestro conjunto de ruedas para Cross Country definitivo. La XRC 1200 SPLINE rompe todos los esquemas de tu conjunto para Cross Country favorito. Ahora es tu turno de batir récords.','Llantas DT SWISS XRC 1200 SPLINE',2490.95,6,1,'llantas_dtswiss.jpg')
INSERT INTO product (descripcion, name, price, stock, category_id,imagefile) VALUES('Entra de lleno en el mundo del BTT con la cubierta Maxxis Rekon Race que aporta un rendimiento excepcional en todas las condiciones posibles','Maxxis Rekon Race 2.4WT 120TPI',49.99,14,2,'rekonrace.jpg')
INSERT INTO product (descripcion, name, price, stock, category_id,imagefile) VALUES('PRÖPUS no es un manillar más de XC, es el reflejo de horas de ingenieria para crear un manillar ultraligero y ultraresistente, su diseño unibody y los materiales con los que está construido te permitirán volar sobre el terreno.','PRÖPUS - Manillar MTB integrado de carbono ultraligero',679.99,3,3,'propus.jpg')
INSERT INTO product (descripcion, name, price, stock, category_id,imagefile) VALUES('Gracias a su exclusivo tratamiento de optimización, la cadena UFO Speed ​​de CeramicSpeed ​​te permite ahorrar vatios y mejorar tu rendimiento, ofreciéndote una mayor velocidad y una baja fricción inigualable. La fórmula única de nuestra nueva cera Speed ​​WAX ha sido desarrollada y perfeccionada a lo largo de los años por nuestro propio equipo de química; al igual que el resto de la gama de productos UFO, es totalmente biodegradable y no tóxica. Esta fórmula ha sido validada mediante exhaustivas pruebas tanto en laboratorio como en condiciones reales, incluyendo su uso por parte de triatletas campeones del mundo y en las tres Grandes Vueltas ciclistas.','CeramicSpeed UFO Racing Chain',169.99,5,4,'ceramic-chain.jpg')
INSERT INTO product (descripcion, name, price, stock, category_id,imagefile) VALUES('Con su construcción BEAM SPIDER, el cassette XTR M9100 de 12 velocidades recorta peso, al tiempo que incrementa otra marcha los desarrollos de MTB de SHIMANO. Con el nuevo cuerpo de buje trasero freehub MICRO SPLINE de SHIMANO y el perfil de dientes HYPERGLIDE+, estos cassettes de 10-45 y 10-51D proporcionan el mejor cambio de MTB del mercado.','Shimano XTR CS-M9100-12',249.99,14,5,'cassette.jpg')
